// HasRequisition applies the HasEdge predicate on the "requisition" edge.
func HasRequisition() predicate.RequisitionLine {
	return predicate.RequisitionLine(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, RequisitionTable, RequisitionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRequisitionWith applies the HasEdge predicate on the "requisition" edge with a given conditions (other predicates).
func HasRequisitionWith(preds ...predicate.Requisition) predicate.RequisitionLine {
	return predicate.RequisitionLine(func(s *sql.Selector) {
		step := newRequisitionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RequisitionLine) predicate.RequisitionLine {
	return predicate.RequisitionLine(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RequisitionLine) predicate.RequisitionLine {
	return predicate.RequisitionLine(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RequisitionLine) predicate.RequisitionLine {
	return predicate.RequisitionLine(sql.NotPredicates(p))
}
